function f = loss_function(x, sinr_data, bound) 
alpha = x(1); 
beta = x(2); 
% 计算模型预测值 
mcs_pred = model_fun(alpha, beta, sinr_data); 
% 计算与边界的平方差 
lower_bound = bound(:,1); 
upper_bound = bound(:,2); 
% 初始化损失 
loss = 0; 
% 对每个样本计算损失 
for i = 1:length(mcs_pred) 
pred = mcs_pred(i); 
lb = lower_bound(i); 
ub = upper_bound(i); 
% 如果预测值在范围内，不施加惩罚 
if pred >= lb && pred <= ub 
% 不添加惩罚项 
else 
% 如果预测值小于下界，计算与下界的平方差 
if pred < lb 
loss = loss + (pred - lb)^2; 
% 如果预测值大于上界，计算与上界的平方差 
elseif pred > ub 
loss = loss + (pred - ub)^2; 
end 
% 添加额外惩罚项 
penalty = 10; % 惩罚系数，可调整 
loss = loss + penalty; 
end 
end 
% 添加参数正则化项，防止参数过大 
lambda = 0.01; % 正则化系数，可调整 
reg_term = lambda * (alpha^2 + beta^2); 
% 总损失 
f = loss + reg_term; 
end 

