    if not path or len(path) < 2: 
        return True 
    for i in range(1, len(path)): 
        current = path[i] 
        for j in range(i): 
            prev = path[j] 
            if not (current[0] > prev[0] and current[1] > prev[1] and current[2] > prev[2]): 
                return False 
    return True 
