def compute_shannon_diversity_index(self, matrix: np.ndarray) -> float:
"""计算Shannon 多样性指数"""
# 统计各元素类型的面积占比
total_area = matrix.size
element_counts = np.bincount(matrix.flatten(), minlength=8)
proportions = element_counts / total_area
# 计算Shannon 指数：SHDI = -∑(Pi × ln Pi)
shdi = 0.0
for p in proportions:
if p > 0:
shdi -= p * np.log(p)
return shdi
